-- All fixture records, notifications and evidence metadata are rolled back.
begin;
do $$
declare a uuid; ae text; f uuid; f2 uuid; b uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid();
 report uuid; revision uuid; release_id uuid; p1 uuid; p2 uuid; rows jsonb; data jsonb; path text; expected_failure boolean;
begin
 select u.id,u.email into a,ae from auth.users u join public.superadmin_emails s on lower(s.email)=lower(u.email) limit 1;
 select user_id into f from public.manufacturer_profiles where onboarding_complete and status is distinct from 'paused' and user_id is distinct from a limit 1;
 select user_id into f2 from public.manufacturer_profiles where onboarding_complete and status is distinct from 'paused' and user_id<>f limit 1;
 if a is null or f is null then raise exception 'Live QC verification requires an admin and an onboarded manufacturer';end if;
 perform set_config('request.jwt.claims','{}',true);
 insert into auth.users(id,email,raw_user_meta_data)values(b,'qc-report-'||b||'@example.invalid','{}'),(outsider,'qc-report-'||outsider||'@example.invalid','{}');
 insert into public.orders(id,user_id,kind,product_name,garment_type,status,status_label)values(oid,b,'production','Simplified QC rollback fixture','T-shirts','submitted','Submitted');
 perform set_config('app.routing_write',oid::text,true);perform set_config('app.workflow_write',oid::text,true);
 update public.orders set assigned_manufacturer_id=f,status='processing',factory_status='in_production',production_released_at=now(),payment_verified_at=now(),paid_amount_cents=10000,selected_price_option_id='bulk',price_options='[{"id":"bulk","label":"T-shirts","totalUnits":10,"priceCents":10000,"currency":"GBP"}]',order_quantities='{"bulkRuns":[{"id":"bulk","kind":"bulk","targetTotal":10,"bySize":{"m":5,"l":5}}]}' where id=oid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);execute 'set local role authenticated';
 report:=public.qc_action(oid,'start_report','{}');
 if report is distinct from public.qc_action(oid,'start_report','{}') then raise exception 'Duplicate draft created';end if;
 select jsonb_agg(value||jsonb_build_object('produced',(value->>'ordered')::integer)) into rows from jsonb_array_elements(public.qc_report_context(oid)->'ordered_lines');
 data:=jsonb_build_object('id',report,'production_summary','Completed garments and printing inspected.','produced_lines',rows,'has_issues',false,'issue_description','','manufacturer_confirmed',true,'photo_ids','[]'::jsonb,'supporting_ids','[]'::jsonb);
 expected_failure:=false;begin perform public.qc_action(oid,'submit_report',data);exception when others then expected_failure:=position('photo' in sqlerrm)>0;end;if not expected_failure then raise exception 'Missing photo was not rejected';end if;
 execute 'reset role';
 path:=oid||'/'||f||'/front.jpg';insert into storage.objects(bucket_id,name,metadata)values('qc-evidence',path,'{"mimetype":"image/jpeg","size":2048}');
 execute 'set local role authenticated';p1:=public.qc_action(oid,'report_evidence',jsonb_build_object('id',report,'path',path,'file_name','front.jpg','file_role','photo'));execute 'reset role';
 path:=oid||'/'||f||'/back.png';insert into storage.objects(bucket_id,name,metadata)values('qc-evidence',path,'{"mimetype":"image/png","size":2048}');
 execute 'set local role authenticated';p2:=public.qc_action(oid,'report_evidence',jsonb_build_object('id',report,'path',path,'file_name','back.png','file_role','photo'));
 data:=data||jsonb_build_object('photo_ids',jsonb_build_array(p1,p2));
 expected_failure:=false;begin perform public.qc_action(oid,'submit_report',data||'{"manufacturer_confirmed":false}');exception when others then expected_failure:=position('accuracy' in sqlerrm)>0;end;if not expected_failure then raise exception 'Missing confirmation was not rejected';end if;
 expected_failure:=false;begin perform public.qc_action(oid,'submit_report',data||'{"has_issues":true}');exception when others then expected_failure:=position('Explain' in sqlerrm)>0;end;if not expected_failure then raise exception 'Missing issue description was not rejected';end if;
 rows:=jsonb_set(rows,'{0,produced}','4');
 expected_failure:=false;begin perform public.qc_action(oid,'submit_report',data||jsonb_build_object('produced_lines',rows));exception when others then expected_failure:=position('discrepancies' in sqlerrm)>0;end;if not expected_failure then raise exception 'Size shortage did not require an explanation';end if;
 data:=data||jsonb_build_object('produced_lines',rows,'issue_description','One garment in the first size is held for correction.');
 perform public.qc_action(oid,'submit_report',data);perform public.qc_action(oid,'submit_report',data);
 if not exists(select 1 from public.orders where id=oid and qc_status='pending_review') then raise exception 'Pending Review not persisted';end if;
 expected_failure:=false;begin perform public.qc_action(oid,'approve_report',jsonb_build_object('id',report));exception when others then expected_failure:=true;end;if not expected_failure then raise exception 'Manufacturer approved its own report';end if;
 expected_failure:=false;begin perform public.qc_action(oid,'dispatch',jsonb_build_object('id',gen_random_uuid(),'tracking','BYPASS'));exception when others then expected_failure:=true;end;if not expected_failure then raise exception 'Unapproved dispatch succeeded';end if;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',ae,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.qc_action(oid,'request_report_changes',jsonb_build_object('id',report,'feedback','Complete the missing garment and update the report.'));
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);execute 'set local role authenticated';
 revision:=public.qc_action(oid,'start_report','{}');
 if revision=report or not exists(select 1 from public.qc_inspections where id=report and qc_status='changes_required' and review_note like 'Complete%') then raise exception 'Previous decision was not preserved';end if;
 if not exists(select 1 from public.qc_inspections where id=revision and not manufacturer_confirmed and photo_ids=jsonb_build_array(p1,p2)) then raise exception 'Resubmission evidence or fresh confirmation is incorrect';end if;
 rows:=jsonb_set(rows,'{0,produced}','5');
 data:=data||jsonb_build_object('id',revision,'production_summary','Missing garment completed; finished production verified.','produced_lines',rows);
 perform public.qc_action(oid,'submit_report',data);
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',ae,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.qc_action(oid,'approve_report',jsonb_build_object('id',revision));
 if not exists(select 1 from public.orders where id=oid and qc_status='approved' and status_label='Ready for dispatch') then raise exception 'Approval did not release dispatch readiness';end if;
 select id into release_id from public.qc_shipment_releases where inspection_id=revision and revoked_at is null;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.qc_action(oid,'dispatch',jsonb_build_object('id',release_id,'tracking','QC-ROLLBACK-HANDOVER'));
 if not exists(select 1 from public.orders where id=oid and status='shipping') then raise exception 'Approved dispatch did not persist';end if;
 execute 'reset role';
 if not exists(select 1 from public.portal_notifications where order_id=oid and audience='superadmin') or not exists(select 1 from public.portal_notifications where order_id=oid and user_id=f and audience='manufacturer') then raise exception 'QC notifications missing';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'email','other@example.invalid','role','authenticated')::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.qc_inspections where order_id=oid) or exists(select 1 from storage.objects where bucket_id='qc-evidence' and name=path) then raise exception 'Unrelated account can access private QC';end if;
 execute 'reset role';

 if not exists(select 1 from public.orders where id=oid and completion_due_at=fully_dispatched_at+interval '14 days')then raise exception 'Default deadline missing';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','factory@example.invalid','role','authenticated')::text,true);execute 'set local role authenticated';
 expected_failure:=false;begin perform public.confirm_order_delivery(oid);exception when others then expected_failure:=position('Superadmin' in sqlerrm)>0;end;if not expected_failure then raise exception 'Factory completion bypass';end if;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',ae,'role','authenticated')::text,true);execute 'set local role authenticated';
 perform public.set_order_completion_deadline(oid,now()+interval '16 days',true,'Carrier delay');
 if not exists(select 1 from public.orders where id=oid and completion_on_hold)then raise exception 'Hold not saved';end if;
 perform public.set_order_completion_deadline(oid,now()+interval '16 days',false,'');
 begin
  perform public.confirm_order_delivery(oid,'Rollback test delivery');
  if not exists(select 1 from public.orders where id=oid and status='completed'and completion_method='admin_delivery'and delivery_confirmed_by=a and delivery_confirmed_at is not null)then raise exception 'Manual completion failed';end if;
  raise exception 'rollback_manual_test';
 exception when raise_exception then if sqlerrm<>'rollback_manual_test'then raise;end if;end;
 execute 'reset role';perform set_config('app.delivery_write',oid::text,true);update public.orders set completion_due_at=now()-interval '1 minute'where id=oid;
 perform public.complete_due_orders();
 if not exists(select 1 from public.orders where id=oid and status='completed'and completion_method='automatic'and delivery_confirmed_at is null)then raise exception 'Automatic completion failed';end if;
 if has_function_privilege('authenticated','public.complete_due_orders()','execute')then raise exception 'Worker exposed';end if;
 if not exists(select 1 from cron.job where jobname='ceriga-complete-delivery-orders'and active and schedule='*/5 * * * *')then raise exception 'Scheduler not active';end if;
end $$;
rollback;
select 'PASS: live QC dispatch, 14-day deadline, manufacturer isolation, admin delivery, pause/resume, automatic completion and active cron. All fixtures rolled back.'as verification;
